action.mutation:
mutation DeleteWorkunit($payload: [WorkunitDeletePayloadInput!]!, $scrapReasonsPayload: [WorkunitScrapReasonDeletePayloadInput!]!) {
  deleteWorkunitScrapReason(payload: $scrapReasonsPayload) {
    id
  }
  mutation: deleteWorkunit(payload: $payload) {
    id
    code
  }
}

mutation DeleteState($payload: [StateDeletePayloadInput!]!) {
  mutation: deleteState(payload: $payload) { 
    id
    id
  }
}

mutation DeleteStateList($payload: [StateListDeletePayloadInput!]!) {
  mutation: deleteStateList(payload: $payload) { 
    id
    id
  }
}
